function fastestRepair(ranks: number[], cars: number): number {
  // heap of [finish time if this mechanic takes one more car, rank, cars so far]
  const h: number[][] = [];
  const less = (a: number[], b: number[]) => a[0] < b[0];
  const push = (x: number[]) => {
    h.push(x);
    let i = h.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!less(h[i], h[p])) break;
      [h[i], h[p]] = [h[p], h[i]]; i = p;
    }
  };
  const pop = () => {
    const top = h[0], last = h.pop()!;
    if (h.length) {
      h[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < h.length && less(h[l], h[m])) m = l;
        if (r < h.length && less(h[r], h[m])) m = r;
        if (m === i) break;
        [h[i], h[m]] = [h[m], h[i]]; i = m;
      }
    }
    return top;
  };
  for (const r of ranks) push([r, r, 0]);
  let worst = 0;
  for (let k = 0; k < cars; k++) {
    const [t, r, m] = pop();
    worst = Math.max(worst, t);
    push([r * (m + 2) * (m + 2), r, m + 1]);
  }
  return worst;
}

