function fastestRepair(ranks: number[], cars: number): number {
  const isqrt = (x: number): number => {
    let m = Math.floor(Math.sqrt(x));
    while (m * m > x) m--;
    while ((m + 1) * (m + 1) <= x) m++;
    return m;
  };
  const enough = (t: number): boolean => {
    let done = 0;
    for (const r of ranks) {
      done += isqrt(Math.floor(t / r));
      if (done >= cars) return true;
    }
    return false;
  };
  let lo = 1, hi = Math.min(...ranks) * cars * cars;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (enough(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

