function fastestRepair(ranks: number[], cars: number): number {
  const count = new Array(101).fill(0);
  for (const r of ranks) count[r]++;
  const isqrt = (x: number): number => {
    let m = Math.floor(Math.sqrt(x));
    while (m * m > x) m--;
    while ((m + 1) * (m + 1) <= x) m++;
    return m;
  };
  let best = 1;
  while (count[best] === 0) best++;
  let lo = 1, hi = best * cars * cars;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    let done = 0;
    for (let r = 1; r <= 100; r++) if (count[r]) done += count[r] * isqrt(Math.floor(mid / r));
    if (done >= cars) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

